class Solution {
public:
    double myPow(double x, int n) {
        long long e = n;
        double base = x, res = 1.0;
        if (e < 0) {
            base = 1 / base;
            e = -e;
        }
        while (e > 0) {
            if (e & 1) res *= base;
            base *= base;
            e >>= 1;
        }
        return res;
    }
};
